x-codeSamples.source:
import { Lenz } from "lenz-io";

const client = new Lenz();  // no api_key needed
const page = await client.library.listLibrary({ page: 1, sort: "recent" });
page.items.forEach(v => console.log(v.claim, "→", v.verdict));

import { Lenz } from "lenz-io";

const client = new Lenz({ apiKey: "lenz_..." });
const v = await client.verifyAndWait({ claim: "Sharks don't get cancer" });
// Add depth: "low" for a shallower check that returns sooner.
console.log(v.verdict, v.lenz_score);
// false 2.0

import { Lenz } from "lenz-io";

const client = new Lenz({ apiKey: "lenz_..." });
const batch = await client.verifyBatch({
  claims: [
    { text: "The Eiffel Tower is in Berlin." },
    { text: "Water boils at 100°C at sea level." },
  ],
});
batch.items.forEach(i => console.log(i.taskId, i.claimText));

import { Lenz } from "lenz-io";

const client = new Lenz({ apiKey: "lenz_..." });
const out = await client.assess({
  text: "Coffee causes cancer and the earth is flat.",
});
out.claims.forEach(c => {
  console.log(c.claim, "→", c.verdict, c.confidence);
  if (c.rationale) console.log("  ", c.rationale);
});

// Several claims at once: one row per item, same order (up to 20).
const rows = (await client.assess({
  claims: ["Coffee causes cancer.", "The earth is flat."],
})).claims;
rows.forEach(c => {
  console.log(c.error_code ? c.hint : c.verdict);
  if (c.dissent) console.log("   One reviewer disagreed:", c.dissent);
});

import { Lenz } from "lenz-io";

const client = new Lenz({ apiKey: "lenz_..." });
const out = await client.extract({
  text: "Coffee causes cancer and the earth is flat.",
});
out.identifiedClaims.forEach(c => console.log(c));

// typed progress needs lenz-io >= 2.11.0
import { Lenz } from "lenz-io";

const client = new Lenz({ apiKey: "lenz_..." });
const s = await client.getStatus("tsk_abc123");

if (s.status === "processing" && s.progress) {
  const { step, index, total } = s.progress;
  console.log(`${step} — step ${index} of ${total}`);
} else if (s.status === "completed") {
  console.log(s.result!.verdict, s.result!.key_finding);
}

import { Lenz } from "lenz-io";

const client = new Lenz({ apiKey: "lenz_..." });
const u = await client.usage();
console.log(`${u.credits.remaining} credits left`, u.costs);
console.log(`${u.verify.remaining} verify calls left`);
console.log(`${u.assess.remaining} assess calls left`);

import { Lenz } from "lenz-io";

const client = new Lenz({ apiKey: "lenz_..." });
const page = await client.verifications.listVerifications({ page: 1 });
page.items.forEach(v => console.log(v.verificationId, v.verdict));

import { Lenz } from "lenz-io";

const client = new Lenz({ apiKey: "lenz_..." });
const related = await client.verifications.related("vid_abc123", { limit: 5 });
related.items.forEach(r => console.log(r.verification_id, r.claim, r.verdict));

MeUsageExtractOut.description:
Daily ``/extract`` usage (rate-limited per day, not credit-based).

``calls_today`` is the ACCOUNT's counter, shared across all of its keys;
``unlimited`` reports whether the CALLING key bypasses the cap.
